/* ═══════════════════════════════════════════════
   HOOKS
═══════════════════════════════════════════════ */
function useInView(ref, { threshold = 0.07, rootMargin = "0px 0px -20px 0px" } = {}) {
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    if (!ref.current) return;
    const obs = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) { setVisible(true); obs.disconnect(); }
    }, { threshold, rootMargin });
    obs.observe(ref.current);
    return () => obs.disconnect();
  }, [ref, threshold, rootMargin]);
  return visible;
}

function useTheme() {
  const [mode, setMode] = useState(() => {
    try { return localStorage.getItem("themeMode") || "auto"; } catch { return "auto"; }
  });
  const apply = useCallback((m) => {
    const dark = m === "dark" || (m === "auto" && window.matchMedia("(prefers-color-scheme:dark)").matches);
    document.documentElement.classList.toggle("dark", dark);
    try { localStorage.setItem("themeMode", m); } catch {}
    setMode(m);
  }, []);
  useEffect(() => {
    apply(mode);
    const mq = window.matchMedia("(prefers-color-scheme:dark)");
    const h = () => { try { if ((localStorage.getItem("themeMode") || "auto") === "auto") apply("auto"); } catch {} };
    mq.addEventListener("change", h);
    return () => mq.removeEventListener("change", h);
  }, [apply, mode]);
  const cycle = () => {
    const cyc = ["auto", "dark", "light"];
    apply(cyc[(cyc.indexOf(mode) + 1) % cyc.length]);
  };
  const icons = { auto: "🌓", dark: "🌙", light: "☀️" };
  const isDark = mode === "dark" || (mode === "auto" && window.matchMedia("(prefers-color-scheme:dark)").matches);
  return { mode, isDark, icon: icons[mode], cycle };
}

function useActiveSection() {
  const [active, setActive] = useState("");
  useEffect(() => {
    const ids = ["intro", ...SECTIONS.map(s => s.id), "quiz", "videos", "goals", "team"];
    const h = () => {
      for (const id of ids) {
        const el = document.getElementById(id);
        if (!el) continue;
        const r = el.getBoundingClientRect();
        if (r.top <= 120 && r.bottom > 120) { setActive(id); break; }
      }
    };
    window.addEventListener("scroll", h, { passive: true });
    return () => window.removeEventListener("scroll", h);
  }, []);
  return active;
}

/* ═══════════════════════════════════════════════
   THREE.JS HERO CANVAS
═══════════════════════════════════════════════ */
function HeroCanvas() {
  const canvasRef = useRef(null);
  useEffect(() => {
    const cvs = canvasRef.current;
    if (!cvs || !window.THREE) return;
    const THREE = window.THREE;
    const renderer = new THREE.WebGLRenderer({ canvas: cvs, antialias: true, alpha: false, powerPreference: "high-performance" });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x020b18);
    const camera = new THREE.PerspectiveCamera(55, 1, 0.1, 200);
    camera.position.set(0, 0, 9);
    scene.add(new THREE.AmbientLight(0x1a1000, 0.6));
    const dl = new THREE.DirectionalLight(0xffcc44, 1.1);
    dl.position.set(5, 8, 5); scene.add(dl);
    const pl = new THREE.PointLight(0x2d7417, 0.5, 30);
    pl.position.set(-6, -3, -4); scene.add(pl);
    const sp = new Float32Array(180 * 3);
    for (let i = 0; i < 180; i++) {
      sp[i*3]=(Math.random()-.5)*40; sp[i*3+1]=(Math.random()-.5)*40; sp[i*3+2]=(Math.random()-.5)*20-6;
    }
    const sg = new THREE.BufferGeometry();
    sg.setAttribute("position", new THREE.BufferAttribute(sp, 3));
    scene.add(new THREE.Points(sg, new THREE.PointsMaterial({ color:0xffffff, size:0.05, transparent:true, opacity:.5 })));
    const g = new THREE.Group();
    const hM = new THREE.MeshPhongMaterial({ color:0xf59e0b, transparent:true, opacity:.18, shininess:30 });
    const hwM = new THREE.MeshPhongMaterial({ color:0xfbbf24, wireframe:true, transparent:true, opacity:.5 });
    for (let row=-3; row<=3; row++) {
      for (let col=-5; col<=5; col++) {
        const ox=(row%2)*.87*1.0, x=col*1.74+ox, z=row*1.5;
        const hx=new THREE.Mesh(new THREE.CylinderGeometry(.48,.48,.12,6),hM);
        hx.position.set(x,0,z); hx.rotation.y=Math.PI/6; g.add(hx);
        const hw=new THREE.Mesh(new THREE.CylinderGeometry(.49,.49,.14,6),hwM);
        hw.position.set(x,0,z); hw.rotation.y=Math.PI/6; g.add(hw);
      }
    }
    const bM=new THREE.MeshPhongMaterial({color:0x78350f,emissive:0x1a0800,shininess:80});
    const wgM=new THREE.MeshPhongMaterial({color:0xfef3c7,transparent:true,opacity:.4,side:THREE.DoubleSide});
    const eM=new THREE.MeshPhongMaterial({color:0x1c1917,shininess:200});
    [[0,1.5,0],[3.2,1.2,1],[-3.2,1.2,-1]].forEach(([x,y,z])=>{
      const body=new THREE.Mesh(new THREE.SphereGeometry(.3,12,12),bM);
      body.scale.set(1,1.8,1); body.position.set(x,y,z);
      const head=new THREE.Mesh(new THREE.SphereGeometry(.2,10,10),bM);
      head.position.set(x,y+.58,z);
      const e1=new THREE.Mesh(new THREE.SphereGeometry(.07,6,6),eM); e1.position.set(x+.1,y+.62,z+.17);
      const e2=new THREE.Mesh(new THREE.SphereGeometry(.07,6,6),eM); e2.position.set(x-.1,y+.62,z+.17);
      const wg1=new THREE.Mesh(new THREE.PlaneGeometry(.8,.38),wgM); wg1.position.set(x+.56,y+.18,z); wg1.rotation.z=.3;
      const wg2=new THREE.Mesh(new THREE.PlaneGeometry(.8,.38),wgM); wg2.position.set(x-.56,y+.18,z); wg2.rotation.z=-.3;
      g.add(body,head,e1,e2,wg1,wg2);
    });
    scene.add(g);
    function resize() {
      const w=cvs.clientWidth, h=cvs.clientHeight||1;
      renderer.setSize(w,h,false); camera.aspect=w/h; camera.updateProjectionMatrix();
    }
    window.addEventListener("resize",resize,{passive:true}); resize();
    let t=0, last=performance.now(), rafId;
    function loop(now) {
      t+=(now-last)*.001; last=now;
      g.rotation.y=t*.14; g.position.y=Math.sin(t*.3)*.2;
      renderer.render(scene,camera); rafId=requestAnimationFrame(loop);
    }
    rafId=requestAnimationFrame(loop);
    return ()=>{
      cancelAnimationFrame(rafId); window.removeEventListener("resize",resize);
      scene.traverse(o=>{
        if(o.geometry)o.geometry.dispose();
        if(o.material){if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material.dispose();}
      });
      renderer.dispose();
    };
  }, []);
  return <canvas ref={canvasRef} className="ento-hero-canvas" />;
}

/* ═══════════════════════════════════════════════
   LANGUAGE SWITCHER COMPONENT
═══════════════════════════════════════════════ */
function LangSwitcher({ lang, setLang }) {
  return (
    <div className="ento-lang-switcher" dir="ltr">
      {Object.entries(LANG_CONFIG).map(([code, cfg]) => (
        <button
          key={code}
          className={`ento-lang-btn ${lang === code ? "active" : ""}`}
          onClick={() => setLang(code)}
          aria-label={`Switch to ${cfg.label}`}
        >
          {cfg.label}
        </button>
      ))}
    </div>
  );
}

